-- Факты команды читаются с первого дня, за который у хаба есть работы людей (hub_team_since), а не с начала правил
-- дележа: недели до 2026-11-02 всё ещё платит таблица, но «не занесено» видит по ним, кто работал. Первое окно
-- начинается в этот день, раньше окон нет: до него «работ нет» значит «данных нет», а не «никто не работал».
-- Начисления из фактов по-прежнему с недели начала правил: окна раньше неё их не трогают.
--
-- «Не занесено» по окну графика: если доказанное окно фактов покрывает окно смены, а хаб видел человека и до этой смены,
-- и после неё, но смены (не захода) на этой странице в окне не было, — это выходной, не строка. Общий слот нескольких
-- людей — как раньше.

INSERT INTO settings(key, value, note, updated_at) VALUES ('hub_team_since', '2026-10-25',
  'С какого дня (МСК) читать факты команды хаба (hub_team_sync): первый полный день, за который у хаба есть работы людей (расширение начало слать активность 2026-10-24 около полуночи). Раньше начала правил дележа (2026-11-02) — только для «не занесено», начисления из фактов с недели правил; позже начала правил не бывает',
  '2026-11-10T00:00:00+03:00')
ON CONFLICT(key) DO NOTHING;

UPDATE schema_docs
   SET description = 'Что хаб доказал по каждому окну фактов команды (agentTeamSales): неделе МСК, первое — с settings.hub_team_since. status unknown — ответ не принят (нет права read:team, отказ, срез не тот, держатель продажи не из работ, нет страницы гранта): начисления из фактов этой недели «неизвестно», не ноль. Окна раньше недели начала правил дележа — только для «не занесено»'
 WHERE tbl = 'hub_team_sync' AND col = '';
UPDATE schema_docs
   SET description = 'Начало окна: понедельник 00:00 МСК, у первого окна — день settings.hub_team_since'
 WHERE tbl = 'hub_team_sync' AND col = 'window_from';
UPDATE schema_docs
   SET description = '«Не занесено»: дни вкладок без значения за последние 45 дней, по которым хаб показывает деньги человека. В доказанную неделю фактов хаба (fact_weeks ok) у человека, сопоставленного с пользователем хаба, — его доли продаж за день (fact_accruals), день без его работы — выходной, не строка; иначе — деньги страниц недели в окне смены по карточке, но если окно смены лежит в доказанном окне фактов (hub_team_sync ok, с settings.hub_team_since), хаб видел человека до и после него, а смены на странице в окне не было, — выходной, не строка. День до дня, по который выплаты закрыли его долг (payable_days), не строка; вкладка модели, которой нет в непустом people.models, — без окна смены, только по фактам. Только сведения: в долг не идут'
 WHERE tbl = 'payroll_unentered' AND col = '';
